feed:
  {{ site.title }}: what changed
  Release notes from every aesop tool.
  {{ site.base_url }}/news/


  {{ updated or "1970-01-01" }}T00:00:00Z
  {{ site.author }}
{% for n in news[:50] %}
{% set t = tools_by_id.get(n.tool) %}

    {{ t.name if t else n.tool }} {{ n.version }}: {{ n.kind_title | lower }}
    {{ site.base_url }}/news/#{{ n.anchor }}

    {{ n.released }}T00:00:00Z
    {{ n.body_html }}

{% endfor %}
